styl:
.w280 { width: 100%;
  max-width: 280px; }
@media screen and (max-width: 600px) {
  .w280 { max-width: 100% !important; }
}
.brad-full { border-radius: 32px !important; }
.butt-link { font-size: 18px;
  line-height: 27px;
  font-weight: 700;
  text-transform: none;
  text-decoration: none;
  color: #f9f9f9;
  display: block;
  padding: 16px 0 16px;
  text-align: center;
  letter-spacing: 0px; }
.white-bg { background-color: #fff; }
.data { display: inline-block;
  padding: 6px 16px;
  background: rgba(254,122,32,0.19);
  border-radius: 12px;
  font-family: Helvetica !important;
  font-weight: 700;
  font-size: 16px;
  line-height: 20px;
  color: #ff8516;
  text-align: left; }
@media screen and (max-width: 600px) {
  .data { font-size: 14px !important; }
}
.middle-title { font-family: Helvetica !important;
  font-weight: 700;
  font-size: 32px;
  line-height: 42px;
  color: #393a44;
  vertical-align: middle; }
@media screen and (max-width: 600px) {
  .middle-title { font-size: 28px !important;
    line-height: 34px !important; }
}
.text { font-family: Helvetica !important;
  font-size: 18px;
  color: #393a44;
  letter-spacing: 0;
  line-height: 26px;
  font-weight: 400; }
.text.bold { font-weight: 700; }
.pb16 { padding-bottom: 16px; }
.pb32 { padding-bottom: 32px; }
.pt24 { padding-top: 24px; }
.pt44 { padding-top: 44px; }
.h-32 { font-size: 8px;
  line-height: 32px;
  height: 32px; }
